#! /bin/env node
// we may need require to load re2
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
//
// Generated by JSON Model Compiler version 2
// see https://github.com/clairey-zx81/json-model
//
import * as runtime from "json_model_runtime"
const JSON_MODEL_VERSION = "2";

export var check_model_map = new Map()

// check $Aa (.'$Aa')
function json_model_2(val, path, rep)
{
    // .'$Aa'
    // "/^a/"
    let res = typeof val == 'string' && val.startsWith("a")
    if (! res)
        rep !== null && rep.push(["unexpected value for model \"/^a/\" [.'$Aa']", path])
    return res
}

// check $Dd (.'$Dd')
function json_model_5(val, path, rep)
{
    // .'$Dd'
    // "/^d/"
    let res = typeof val == 'string' && val.startsWith("d")
    if (! res)
        rep !== null && rep.push(["unexpected value for model \"/^d/\" [.'$Dd']", path])
    return res
}

// check $bb (.'$bb')
function json_model_3(val, path, rep)
{
    // .'$bb'
    // "/^b/"
    let res = typeof val == 'string' && val.startsWith("b")
    if (! res)
        rep !== null && rep.push(["unexpected value for model \"/^b/\" [.'$bb']", path])
    return res
}

// check $ (.)
function json_model_1(val, path, rep)
{
    // Edit model namespace vs model
    // .
    if (! (val !== null && typeof val == 'object' && !Array.isArray(val)))
    {
        rep !== null && rep.push(["not an object [.]", path])
        return false
    }
    let res
    let must_count = 0
    for (const [prop, pval] of Object.entries(val))
    {
        let lpath_0 = path ? path.concat([prop]) : null
        if (prop == "A")
        {
            // handle must A property
            must_count += 1
            // .A
            res = json_model_2(pval, (path ? lpath_0 : null), rep)
            if (! res)
            {
                rep !== null && rep.push(["unexpected value for model \"$Aa\" [.A]", (path ? lpath_0 : null)])
                rep !== null && rep.push(["invalid mandatory prop value [.A]", (path ? lpath_0 : null)])
                return false
            }
            continue
        }
        if (prop == "b")
        {
            // handle may b property
            // .b
            res = json_model_3(pval, (path ? lpath_0 : null), rep)
            if (! res)
            {
                rep !== null && rep.push(["unexpected value for model \"$bb\" [.b]", (path ? lpath_0 : null)])
                rep !== null && rep.push(["invalid optional prop value [.b]", (path ? lpath_0 : null)])
                return false
            }
            continue
        }
        else if (prop == "d")
        {
            // handle may d property
            // .d
            res = json_model_5(pval, (path ? lpath_0 : null), rep)
            if (! res)
            {
                rep !== null && rep.push(["unexpected value for model \"$Dd\" [.d]", (path ? lpath_0 : null)])
                rep !== null && rep.push(["invalid optional prop value [.d]", (path ? lpath_0 : null)])
                return false
            }
            continue
        }
        rep !== null && rep.push(["unexpected prop [.]", (path ? lpath_0 : null)])
        return false
    }
    if (must_count != 1)
    {
        if (rep !== null)
        {
            if (! val.hasOwnProperty("A"))
                rep !== null && rep.push(["missing mandatory prop <A> [.]", path])
        }
        return false
    }
    return true
}


var initialized = false

// differed module initializations
export function check_model_init()
{
    if (! initialized)
    {
        initialized = true;
        runtime.jm_set_rx(RegExp)
        check_model_map.set("", json_model_1)
        check_model_map.set("Aa", json_model_2)
        check_model_map.set("Dd", json_model_5)
        check_model_map.set("bb", json_model_3)
    }
}

// differed module cleanup
export function check_model_free()
{
    if (initialized)
        initialized = false;
}

export function check_model(val, name, rep)
{
    let checker = check_model_map.get(name)
    if (checker === undefined)
        throw `no checker for "${name}"`
    let path = rep !== null ? [] : null

    return checker(val, path, rep)
}

// possibly run as main based on a guess
import main from "json_model_runtime/main.js"

if (import.meta.url.endsWith(process.argv[1]))
    main(check_model_init, check_model, check_model_free)
